        if (client_sock < 0)
            continue;

        char buffer[MESH_MSG_SIZE + 256];
        int n = recv(client_sock, buffer, sizeof(buffer) - 1, 0);
        close(client_sock);

        if (n <= 0)
            continue;
        buffer[n] = '\0';

