void BeaconDataParse(datap *parser, char *buffer, int size)
{
    parser->original = buffer;
    parser->buffer = buffer;
    parser->length = size;
}

char *BeaconDataPtr(datap *parser, int size)
{
    if (parser->length < size)
        return NULL;
    char *ptr = parser->buffer;
    parser->buffer += size;
    parser->length -= size;
    return ptr;
}

int BeaconDataInt(datap *parser)
{
    char *ptr = BeaconDataPtr(parser, 4);
    if (!ptr)
        return 0;
    return *(int *)ptr;
}

short BeaconDataShort(datap *parser)
{
    char *ptr = BeaconDataPtr(parser, 2);
    if (!ptr)
        return 0;
    return *(short *)ptr;
}

int BeaconDataLength(datap *parser)
{
    return parser->length;
}

char *BeaconDataExtract(datap *parser, int *size)
{
    int len = BeaconDataInt(parser);
    if (len <= 0 || len > parser->length)
        return NULL;
    char *data = BeaconDataPtr(parser, len);
    if (size)
        *size = len;
    return data;
}

void BeaconPrintf(int type, const char *fmt, ...)
{
    if (g_output_len >= sizeof(g_beacon_output) - 1)
        return;
    va_list args;
    va_start(args, fmt);
    int written = vsnprintf(g_beacon_output + g_output_len,
                            sizeof(g_beacon_output) - g_output_len - 1, fmt, args);
    va_end(args);
    if (written > 0)
    {
        g_output_len += (written < (int)(sizeof(g_beacon_output) - g_output_len)
                             ? written
                             : (int)(sizeof(g_beacon_output) - g_output_len - 1));
    }
}

void BeaconOutput(int type, const char *data, int len)
{
    if (len <= 0 || !data)
        return;
    if (g_output_len + len >= sizeof(g_beacon_output))
    {
        len = sizeof(g_beacon_output) - g_output_len - 1;
    }
    memcpy(g_beacon_output + g_output_len, data, len);
    g_output_len += len;
    g_beacon_output[g_output_len] = '\0';
}

