static int hex_to_bytes(const char *hex, unsigned char *out, size_t outlen) {
    size_t hlen = strlen(hex);
    if (hlen != outlen * 2) return -1;
    for (size_t i = 0; i < outlen; i++) {
        unsigned int b;
        if (sscanf(hex + i * 2, "%2x", &b) != 1) return -1;
        out[i] = (unsigned char)b;
    }
    return 0;
}

