def _wait_for_server_ready(self, host, port, timeout=5):
	"""Wait for server to accept connections."""
	start = time.time()
	while time.time() - start < timeout:
		try:
			s = socket.socket()
			s.settimeout(1)
			s.connect((host, port))
			s.close()
			return True
		except (ConnectionRefusedError, socket.timeout):
			time.sleep(0.1)
	return False

